use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    for row in input.as_array() {
        let key = row[0].as_i64().unwrap();
        let value = row[1].as_i64().unwrap();
        result.push(serde_json::Value::Number(value));
    }
    result.sort_by_key(|a, b| a.as_i64().unwrap().cmp(&b.as_i64().unwrap()));
    serde_json::Value::Array(result)
}
